export const profileById = (id) => PROFILES.find((p) => p.id === id);
export const platformById = (id) => ["ps5", "xbox"].find((p) => p === id);
export const PLATFORM_LABEL = {
  ps5: "PlayStation 5",
  xbox: "Xbox Series X|S"
};
const clamp = (n, lo, hi) => Math.min(hi, Math.max(lo, n));
const round1 = (n) => Math.round(n * 10) / 10;
export function resolveWeights(profile, priorities) {
  const out = { ...profile.weights };
  for (const c of priorities)
    out[c] = round1(clamp(out[c] + 0.7, 0.05, 2.7));
  return out;
}
function bonusesFor(edition) {
  return BONUSES.filter((b) => b.editions.includes(edition));
}
function scoreBonus(b, weights) {
  return {
    id: b.id,
    label: b.label,
    category: b.category,
    confidence: b.confidence,
    detail: b.detail,
    utility: round1(b.value * weights[b.category] * CONFIDENCE_WEIGHT[b.confidence])
  };
}
const TIER_ORDER = ["standard", "ultimate"];
export function evaluateEditions(input) {
  const profile = profileById(input.profile) ?? PROFILES[PROFILES.length - 1];
  const platform = platformById(input.platform) ?? "ps5";
  const tolerance = clamp(Math.round(input.upliftTolerance), 0, 200);
  const priorities = input.priorities.filter((p) => (p in CATEGORY_LABEL));
  const weights = resolveWeights(profile, priorities);
  const scored = EDITIONS.map((edition) => {
    const bonuses = bonusesFor(edition.id).map((b) => scoreBonus(b, weights)).sort((a, b) => b.utility - a.utility);
    const utility = round1(bonuses.reduce((s, b) => s + b.utility, 0));
    return { edition, bonuses, utility };
  });
  const baseUtility = scored.find((s) => s.edition.id === "standard").utility;
  const enriched = scored.map((s) => {
    const idx = TIER_ORDER.indexOf(s.edition.id);
    const prevId = idx > 0 ? TIER_ORDER[idx - 1] : undefined;
    const prevIds = prevId ? new Set(bonusesFor(prevId).map((b) => b.id)) : new Set;
    const addedOverPrevious = s.bonuses.filter((b) => !prevIds.has(b.id));
    const utilityDelta = round1(s.utility - baseUtility);
    const uplift = s.edition.upliftPercent;
    const perPoint = uplift === 0 ? 0 : round1(utilityDelta / uplift * 10);
    const available = s.edition.platforms.includes(platform);
    const overBudget = uplift > tolerance;
    const efficiency = uplift === 0 ? 0.9 : clamp(utilityDelta / (uplift / 12), 0, 1.3);
    const categoriesHere = new Set(bonusesFor(s.edition.id).map((b) => b.category));
    const coverage = priorities.length === 0 ? 1 : priorities.filter((c) => categoriesHere.has(c)).length / priorities.length;
    const budgetPenalty = overBudget ? clamp((uplift - tolerance) / 60, 0, 0.9) : 0;
    const raw = (0.3 + efficiency * 0.36 + coverage * 0.22) * (1 - budgetPenalty);
    return {
      ...s,
      available,
      overBudget,
      utilityDelta,
      utilityPerUpliftPoint: perPoint,
      addedOverPrevious,
      confidence: s.edition.confidence,
      score: Math.round(clamp(raw, 0, 1) * 100)
    };
  });
  const ranked = [...enriched].sort((a, b) => {
    if (a.available !== b.available)
      return a.available ? -1 : 1;
    if (b.score !== a.score)
      return b.score - a.score;
    return a.edition.upliftPercent - b.edition.upliftPercent;
  });
  const best = ranked[0];
  const headline = best.edition.label;
  const reason = buildReason(best, profile, tolerance, platform);
  return {
    platform,
    platformLabel: PLATFORM_LABEL[platform],
    profile,
    upliftTolerance: tolerance,
    priorities,
    weights,
    ranked,
    best,
    headline,
    reason,
    upgradeMath: buildUpgradeMath(enriched, tolerance),
    unknowns: UNKNOWNS
  };
}
function buildReason(best, profile, tolerance, platform) {
  if (best.edition.id === "standard") {
    return `${profile.label.toLowerCase()} profiliyle, Standard'ın üzerinde hiçbir şey, ${tolerance}% tavanınla artışı haklı çıkaracak kadar kullanılabilir değer katmıyor ve Standard zaten tüm hikâyeyi ve tüm çevrimiçi modu içeriyor.`;
  }
  return `Standard'a göre yaklaşık ${best.utilityDelta} puan ağırlıklı fayda katıyor, ${best.edition.upliftPercent}% artış karşılığında, harcadığın her %10 için yaklaşık ${best.utilityPerUpliftPoint} puan; bu, ${PLATFORM_LABEL[platform]} üzerinde ${tolerance}% tavanın içinde mevcut kademeler arasında en iyi getiri.`;
}
function buildUpgradeMath(all, tolerance) {
  const standard = all.find((e) => e.edition.id === "standard");
  const ultimate = all.find((e) => e.edition.id === "ultimate");
  const gap = ultimate.edition.upliftPercent - standard.edition.upliftPercent;
  const gain = round1(ultimate.utilityDelta - standard.utilityDelta);
  return [
    {
      title: "Standard'dan Ultimate'a yükseltme",
      body: `Ultimate, Standard'dan yaklaşık %${gap} daha pahalı ve oyun tarzın için yaklaşık ${gain} puan ağırlıklı fayda ekliyor. Bu sayı 3'ün altındaysa, adım senin için kozmetiktir; 6'nın üzerindeyse sayfadaki en ucuz faydadır.`
    },
    {
      title: "Şimdi Standard, sonra yükselt",
      body: "Konsolda dijital kademe yükseltmeleri normalde fiyat farkı karşılığında mağaza içi yükseltme olarak satılır, bu yüzden Standard alıp sonra yükselmek genelde toplamda aynı tutar; bir uyarıyla: çıkış dönemi bonus haftaları ve erken erişim avantajları sona erer ve bunları geriye dönük alamazsın."
    },
    {
      title: "Kademe yerine para almak",
      body: "Bir oyuncu için dürüst karşılaştırma kademe artışı ile Standard değil, kademe artışı ile çıkıştan sonra aynı miktarda oyun içi parayı almak, gerçek oyun içi fiyatları öğrendikten sonra. Para, yükseltmenin tek nedeni ise bekle."
    },
    {
      title: "Belirttiğin tavan",
      body: `Standard'ın ${tolerance}% üzerine çıkacağını söyledin. Bunun üzerindeki her şey gizlenmek yerine tabloda işaretlenir, böylece neyi almamayı seçtiğini görebilirsin.`
    }
  ];
}
